Slides.exampleCode:
// Usage 1: Method chaining
ppt.useSlide(1)
   .addText('Hello', { x: 100, y: 100 })
   .addShape('rectangle', { x: 100, y: 100, width: 100, height: 100 });

// Usage 2: Assigned instance handles
const slide1 = ppt.useSlide(1);
const slide2 = ppt.useSlide(2);

slide1.addText('Hello', { x: 100, y: 100 });
slide2.addShape('circle', { x: 100, y: 100, width: 100, height: 100 });

// Add empty slide at the end
ppt.addSlide();

// Add slide at position 2, shifting remaining slides next
ppt.addSlide({ layout: 'Title and Content' }, 2);

// Duplicate slide 1 and insert at position 2
await ppt.duplicateSlide(1, 2);

// Duplicate last slide and append to the end
await ppt.duplicateSlide();

// Remove slide 3
ppt.removeSlide(3);

// Remove last slide
ppt.removeSlide();

const slides = ppt.getSlides();
console.log(`Inspected ${slides.length} slides.`);
console.log(slides[0].titles, slides[0].tables, slides[0].transitions);

// Get metadata of slide 2
const slideMeta = ppt.getSlide(2);

// Get metadata of active slide
ppt.useSlide(1);
const activeMeta = ppt.getSlide();

const sourceDeck = await PPTXTemplater.load('catalog.pptx');

// Import slide 3 from sourceDeck to position 2 of current deck
await ppt.importSlideFrom(sourceDeck, 3, 2);

// Export slides 1 and 3 into a new presentation instance
const newDeck = await ppt.exportSlides(1, 3);
await newDeck.saveToFile('./output/summary.pptx');

// Target a section by name and execute replacements across its slides
ppt.useSection('Financials')
   .replaceText({ '{{quarter}}': 'Q3', '{{status}}': 'Audited' });

// Target a section containing slide 5
ppt.useSection(5)
   .replaceText({ '{{CONFIDENTIAL}}': 'INTERNAL ONLY' });

// Create a section starting at slide 1
ppt.addSection('Introduction', 1);

// Create another section starting at slide 4
ppt.addSection('Financials', 4);

ppt.updateSection('Financials', {
  newName: 'Q3 Financial Overview'
});

// Remove section grouping only (keeps slides)
ppt.removeSection('Appendix');

// Remove section and all its slides
ppt.removeSection('Deprecated', true);

// 1. Query by section name
const finSection = ppt.getSection('Financials');

// 2. Query by slide number to discover containing section
const currentSection = ppt.getSection(4);

// 3. Chain slides from section directly into useSlide
if (finSection) {
  ppt.useSlide(...finSection.slideIndices)
     .replaceText({ '{{CONFIDENTIAL}}': 'TRUE' });
}

// Hide active slide
ppt.useSlide(2).hideSlide();

// Hide multiple slides by index
ppt.hideSlide(3, 4);

// Unhide slide 2
ppt.unhideSlide(2);

// Unhide multiple slides
ppt.unhideSlide(3, 4);

// Reset active slide completely
ppt.useSlide(2).resetSlide();

// Reset slide 3 while keeping layout placeholders intact
ppt.resetSlide(3, { preservePlaceholders: true });

// 1. Add comment to the active slide
await ppt.useSlide(1).addComment('Please verify these revenue projections before publishing.', {
  author: 'Sarah Connor',
  initials: 'SC'
});

// 2. Add pinned comment at specific slide coordinates
await ppt.addComment('Update chart legend styling here.', {
  slideRef: 2,
  author: 'Design Lead',
  x: '4.5in',
  y: '2.0in'
});

// 1. Remove all comments from active slide
await ppt.useSlide(1).removeComment();

// 2. Remove comment by 1-based comment index on slide 2
await ppt.removeComment(1, { slideRef: 2 });

// 3. Remove comments matching author name
await ppt.removeComment('Sarah Connor', { slideRef: 1 });

